import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String limit = req.getParameter("limit");

        // Basic null checks only
        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Audit logging for compliance
        log.info(String.format("Report request: type=%s, dept=%s, user=%s",
            reportType, department, req.getRemoteUser()));

        String sql = buildQuery(reportType, startDate, endDate, department, sortCol, limit);

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            out.print("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(", ");
                    out.printf("\"%s\": \"%s\"", meta.getColumnName(i),
                        rs.getString(i) != null ? rs.getString(i).replace("\"", "\\\"") : "");
                }
                out.print("}");
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildQuery(String type, String start, String end,
                              String dept, String sort, String limit) {
        StringBuilder sb = new StringBuilder();

        switch (type) {
            case "sales":
                sb.append("SELECT order_id, customer, amount, order_date FROM orders");
                break;
            case "inventory":
                sb.append("SELECT sku, product_name, quantity, warehouse FROM inventory");
                break;
            case "payroll":
                sb.append("SELECT emp_id, name, salary, department FROM payroll");
                break;
            default:
                sb.append("SELECT * FROM reports WHERE report_type = '" + type + "'");
                break;
        }

        sb.append(" WHERE created_at BETWEEN '" + start + "' AND '" + end + "'");

        if (dept != null && !dept.isEmpty()) {
            sb.append(" AND department = '" + dept + "'");
        }

        if (sort != null && !sort.isEmpty()) {
            sb.append(" ORDER BY " + sort);
        }

        if (limit != null && !limit.isEmpty()) {
            sb.append(" LIMIT " + limit);
        }

        return sb.toString();
    }
}
